from fastapi import FastAPI, Depends
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer
from fastapi.testclient import TestClient
from typing import Annotated

app = FastAPI()
security = HTTPBearer()

@app.get("/users/me")
def read_current_user(
    credentials: Annotated[HTTPAuthorizationCredentials, Depends(security)]
):
    return {"scheme": credentials.scheme, "credentials": credentials.credentials}

client = TestClient(app)

def test_authorization_header_whitespace():
    # Test case 1: Single space (correct)
    response = client.get("/users/me", headers={"Authorization": "Bearer xxx"})
    assert response.json() == {"scheme": "Bearer", "credentials": "xxx"}

    # Test case 2: Multiple spaces
    response = client.get("/users/me", headers={"Authorization": "Bearer   xxx"})
    print(f"Multiple spaces response: {response.json()}")
    assert response.json() == {"scheme": "Bearer", "credentials": "xxx"}

    # Test case 3: Trailing whitespace
    response = client.get("/users/me", headers={"Authorization": "Bearer xxx "})
    print(f"Trailing whitespace response: {response.json()}")
    assert response.json() == {"scheme": "Bearer", "credentials": "xxx"}

if __name__ == "__main__":
    try:
        test_authorization_header_whitespace()
        print("All tests passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        import sys
        sys.exit(1)

